// Monta o e-mail ao setor responsável. Para mudar textos/assunto, edite só este nó.
const b = $('Webhook').first().json.body;
const i = b.payload || {};

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmt = (d) => (d?.nome ? `${d.nome} <${d.email}>` : d?.email);
const tipo = i.tipoDocumentoLabel || 'Contrato';
const empresa = i.empresa?.nome || '';
const from = i.remetente || 'BMS Consultoria Tributária <no-reply@bmsprojetos.com>';
const data = i.assinadoEm ? new Date(i.assinadoEm).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }) : '';
const p = (t) => `<p style="margin:0 0 12px 0;font-size:14px;line-height:1.6;">${t}</p>`;
const botao = (url, texto, sec = false) => url ? `<a href="${esc(url)}" style="display:inline-block;margin:4px;background:${sec ? '#ffffff' : '#E8620E'};color:${sec ? '#0F2A47' : '#ffffff'};border:1px solid ${sec ? '#D6DEE8' : '#E8620E'};text-decoration:none;padding:12px 22px;border-radius:8px;font-size:14px;font-weight:700;">${esc(texto)}</a>` : '';
const linha = (k, v) => v ? `<tr><td style="padding:6px 12px 6px 0;font-size:13px;color:#6B7A8D;white-space:nowrap;vertical-align:top;">${esc(k)}</td><td style="padding:6px 0;font-size:13px;color:#0F2A47;">${v}</td></tr>` : '';

const produtos = (i.produtos || []).map((x) => esc(x.nome)).join(', ');
const objetos = (i.objetos || []).map(esc).join(', ');
const semSetor = (i.semSetor || []).length
  ? p(`<span style="font-size:13px;color:#B4423A;">Atenção: ${esc(i.semSetor.join(', '))} não tem setor cadastrado e não recebeu este aviso.</span>`) : '';
const contato = i.comercial?.nome
  ? p(`<span style="font-size:13px;color:#3A4A5E;">Comercial responsável: <strong>${esc(i.comercial.nome)}</strong> (<a href="mailto:${esc(i.comercial.email)}" style="color:#E8620E;">${esc(i.comercial.email)}</a>).</span>`) : '';

const html = `<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width, initial-scale=1" /></head>
<body style="margin:0;padding:0;background:#F3F5F8;font-family:Arial,Helvetica,sans-serif;color:#0F2A47;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#F3F5F8;padding:32px 12px;"><tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%;background:#ffffff;border:1px solid #E3E8EF;border-radius:10px;overflow:hidden;">
  <tr><td style="background:#0F2A47;padding:24px 32px;">
    <div style="color:#ffffff;font-size:22px;font-weight:700;letter-spacing:0.06em;">BMS</div>
    <div style="margin-top:2px;color:#F2A46B;font-size:10px;letter-spacing:0.28em;text-transform:uppercase;">Consultoria Tributária</div>
  </td></tr>
  <tr><td style="height:3px;background:#E8620E;"></td></tr>
  <tr><td style="padding:32px 32px 8px 32px;">
    <p style="margin:0 0 8px 0;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:#6B7A8D;">${esc(tipo)} · assinado</p>
    <h1 style="margin:0 0 16px 0;font-size:22px;line-height:1.3;color:#0F2A47;">${esc(empresa)}</h1>
    ${p('Olá,')}
    ${p(`O contrato <strong>${esc(i.titulo)}</strong> foi assinado por todas as partes${data ? ` em ${esc(data)}` : ''} e está liberado para execução pelo seu setor.`)}
    <table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 16px 0;">
      ${linha('Cliente', `${esc(empresa)}${i.empresa?.cnpj ? ` · CNPJ ${esc(i.empresa.cnpj)}` : ''}`)}
      ${linha('Oportunidade', esc(i.oportunidade))}
      ${linha('Produtos', produtos)}
      ${linha('Objeto', objetos)}
    </table>
    ${p('O PDF assinado segue em anexo.')}
    ${contato}
    ${semSetor}
  </td></tr>
  <tr><td style="padding:4px 32px 8px 32px;text-align:center;">
    ${botao(i.links?.pdfAssinado, 'Baixar contrato assinado')}${botao(i.links?.juridico, 'Abrir no sistema', true)}
  </td></tr>
  <tr><td style="padding:28px 32px 0 32px;"><div style="border-top:1px solid #E3E8EF;"></div></td></tr>
  <tr><td style="padding:16px 32px 24px 32px;text-align:center;">
    <p style="margin:0 0 4px 0;font-size:12px;color:#0F2A47;font-weight:700;">BMS Consultoria Tributária</p>
    <p style="margin:0;font-size:11px;color:#8A9AAC;">Aviso automático do jurídico. O link do PDF expira em 30 dias.</p>
  </td></tr>
</table></td></tr></table></body></html>`;

const nomeArquivo = `${i.titulo || 'Contrato'} - assinado.pdf`.replace(/[\\/:*?"<>|]/g, '-');
return [{ json: {
  eventoId: b.eventoId,
  from,
  to: (i.para || []).map(fmt),
  cc: (i.cc || []).map(fmt),
  subject: `Contrato assinado: ${tipo} — ${empresa} (liberado para execução)`,
  html,
  attachments: i.links?.pdfAssinado ? [{ filename: nomeArquivo, path: i.links.pdfAssinado }] : [],
} }];

